public class Main {
    static int best;

    static int maxPathSum(TreeNode root) {
        best = Integer.MIN_VALUE;
        gain(root);
        return best;
    }

    static int gain(TreeNode node) {
        if (node == null) return 0;
        int left = Math.max(gain(node.left), 0);                  // clamp negative contributions to 0
        int right = Math.max(gain(node.right), 0);
        best = Math.max(best, node.val + left + right);              // full path THROUGH this node, both sides
        return node.val + Math.max(left, right);                       // single best side, offered to the parent
    }
}

